#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    long val;
    struct Node *next;
} Node;

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    Node *head = NULL;
    for (int i = 1; i < argc; ++i) {
        long v = strtol(argv[i], NULL, 10);
        Node *newNode = malloc(sizeof(Node));
        if (!newNode) {
            perror("malloc");
            return 1;
        }
        newNode->val = v;
        // Insert in ascending order
        if (!head || head->val > v) {
            newNode->next = head;
            head = newNode;
        } else {
            Node *cur = head;
            while (cur->next && cur->next->val <= v) {
                cur = cur->next;
            }
            newNode->next = cur->next;
            cur->next = newNode;
        }
    }
    for (Node *p = head; p; p = p->next) {
        printf("%ld", p->val);
        if (p->next) putchar(' ');
    }
    putchar('\n');
    // Free allocated memory (optional)
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }
    return 0;
}
